-0.05262462, 0.013998826, 0.0352469, 0.037713263, -0.10886611, 0.0051667066, 0.008777735, -0.06310889, 0.02322422, -0.07177315, -0.033559754, -0.056784052, -0.08584519, 0.025908396, -0.0028530364, 0.016323257, -0.11305964, 0.0043922015, -0.02163249, -0.08076879, -0.0044556404, -0.062851295, 0.008823683, -0.053083587, 0.02475359, 0.054839063, -0.012967495, -0.013211615, 0.060071953, 0.053001072, -0.073585704, 0.0648197, 0.009675487, -0.050898157, -0.0169026, -0.032788657, -0.07133083, 0.010931403, -0.09409653, 0.0032002553, 0.050901916, -0.045379903, 0.07031011, -0.00441135, -0.013621811, 0.06802905, 0.009134186, 0.076004885, -0.020222768, 0.013610094, -0.024513729, -0.042308982, 0.0010200491, -0.06333181, -0.037879042, -0.14330648, -0.026445577, 0.059243076, 0.11623683, 0.02434141, 0.0035859197, 0.0036576206, -0.035087876, -0.012683857, -0.05309684, 0.032784794, -0.021658614, 0.0074724364, -0.03386419, 0.009585348, 0.01378707, 0.056575682, 0.10528941, -0.033896077, 4.771067e-34, -0.031724133, -0.012436926, -0.037023064, -0.013610573, 0.041294776, -0.04658332, -0.0914573, -0.05072927, 0.06661754, -0.035353716, -0.049954165, -0.01862339, -0.004792832, 0.039626803, -0.0068906774, -0.073927686, 0.013287893, -0.020368181, -0.056765463, 0.036783423, 0.04679982, -0.0011138475, -0.1079224, 0.019478843, 0.07787036, -0.009366513, 0.04872835, 0.03033003, 0.06329986, -0.0031587405, -0.01284537, -0.013126967, 0.04631089, -0.12684998, 0.0017907874, 0.024577813, -0.03682125, -0.10055821, -0.030328922, -0.0038321263, 0.08705196, -0.00031064928, -0.0015473794, -0.02846816, -0.087249175, 0.047093406, 0.08986617, -0.0459297, -0.06542202, 0.03925362, 0.022072287, -0.026893076, -0.003878549, -0.0072054085, 0.011365486, -0.012591671, 0.031543963, 0.05127927, 0.0063033183, 0.01547134, 0.03846173, -0.0023883532, -0.0053380574, 0.080835514, 0.007159935, -0.046400223, 0.033480078, 0.025910214, -0.09267847, 0.022385053, 0.022082608, -0.019284828, -0.037021775, -0.043715283, -0.07300452, -0.04