0.009221756, -0.04349406, 0.043804113, 0.023917696, 0.028306043, 0.009219718, -0.011963082, 0.023514614, -0.0036999616, 0.020498358, -0.09023922, -0.071771465, 0.033064045, 0.084557526, -0.053518377, -0.068718344, -0.0011248393, 0.022088755, -0.008242659, -0.010177404, -0.014764629, -0.014115091, -0.0058190376, -0.07163834, 0.019379972, -0.008755011, 0.014907034, 0.05619422, -0.033149038, -0.09052098, -0.01830262, -0.072679766, 0.00865957, 0.03750835, 0.03599072, -0.06266088, -0.0211851, -0.085165784, -0.0057812296, -0.006268878, -0.037495777, -0.11584982, -0.07564541, -0.010028664, 0.033781648, 0.031445358, 0.052788593, 0.039868396, -0.043936707, -0.022872517, 0.046375327, 0.07221535, 0.00823802, -0.00075239403, -0.058825172, 0.03548069, 0.06433289, 0.13452458, -0.016284134, 0.019214235, 0.0035976411, 0.023138084, 0.022230608, -0.016291225, 0.056932412, 0.039756786, 0.054886132, 0.031723928, -0.07755643, 0.049160853, -0.04578492, 0.15266462, -0.008433591, 3.3167122e-34, 0.03629116, 0.018338019, -0.080596365, -0.052221075, 0.07592285, -0.069733985, -0.012779876, -0.047799572, 0.025360826, -0.06090324, -0.045359027, -0.00021812312, -0.019949095, 0.007772222, 0.0064730817, -0.056468103, -0.04983306, -0.06929694, -0.010978989, 0.010994317, -0.007837292, -0.09783106, -0.038935695, 0.06467553, 0.022763839, -0.06393225, 0.08325197, 0.06597828, 0.007022003, -0.037786964, -0.017885672, -0.04422485, 0.01980086, 0.014440554, -0.037680775, 0.037207436, 0.047641493, -0.15873757, -0.0050261784, -0.012787614, 0.071725085, 0.04435034, 0.012669217, -0.058590032, -0.045913298, 0.03276951, 0.08899762, 0.03157794, 0.076392226, 0.04223114, -0.002826804, 0.089293905, -0.10262232, -0.017355356, -0.002250633, -0.018299012, -0.019056182, -0.07343748, -0.009261595, 0.03526226, 0.02081389, 0.07583802, 0.077733114, 0.04500649, -0.035238404, -0.060756534, -0.06867238, -0.025625177, 0.0034715694, -0.015631251, 0.12769206, -0.03470269, 0.005264712, 0.01672563, -0.0089656245, -0.08774596, -0.0493