# ---------------------------------------------------------------------------
# Seed functions
# ---------------------------------------------------------------------------

async def seed_ai_models(conn) -> int:
    result = await conn.execute(
        text("""
            INSERT INTO ai_models
                (id, provider, model_name, description,
                 is_active, supports_analysis, supports_optimization)
            VALUES
                (:id, :provider, :model_name, :description,
                 :is_active, :supports_analysis, :supports_optimization)
            ON CONFLICT (provider, model_name) DO NOTHING
        """),
        AI_MODELS,
    )
    return result.rowcount


async def seed_templates(conn) -> int:
    """Insert templates one at a time.

    asyncpg does not allow mixing named bind-params (:name) with Postgres
    cast-shorthand (::type) in the same statement.  We work around this by:
      - passing tags as a pre-serialised JSON string and casting it in SQL
      - passing embeddings as a pre-formatted '[f1,f2,…]' string and casting
        it in SQL using separate, unambiguous parameter names.
    """
    inserted = 0
    for row in TEMPLATES:
        tags_json = json.dumps(row["tags"])
        emb = row["embedding"]

        if emb is not None:
            # Format as Postgres vector literal: '[0.1,0.2,...]'
            emb_str = "[" + ",".join(str(f) for f in emb) + "]"
            emb_sql = "CAST(:emb_str AS vector)"
        else:
            emb_str = None
            emb_sql = "NULL"

        result = await conn.execute(
            text(f"""
                INSERT INTO templates
                    (id, title, description, body, mode, category,
                     ai_model_id, tags, embedding,
                     is_featured, is_approved, use_count, role)
                VALUES
                    (:id, :title, :description, :body, :mode, :category,
                     :ai_model_id, CAST(:tags_json AS jsonb), {emb_sql},
                     :is_featured, :is_approved, :use_count, :role)
                ON CONFLICT (id) DO NOTHING
            """),
            {
                "id": row["id"],
                "title": row["title"],
                "description": row["description"],
                "body": row["body"],
                "mode": row["mode"],
                "category": row["category"],
                "ai_model_id": row["ai_model_id"],
                "tags_json": tags_json,
                "emb_str": emb_str,
                "is_featured": row["is_featured"],
                "is_approved": row["is_approved"],
                "use_count": row["use_count"],
                "role": row["role"],
            },
        )
        inserted += result.rowcount
    return inserted


async def seed_style_profiles(conn) -> int:
    inserted = 0
    for row in STYLE_PROFILES:
        # attributes is stored as a JSON string in the data; pass it pre-cast.
        result = await conn.execute(
            text("""
                INSERT INTO style_profiles
                    (id, name, type, attributes, injection_template,
                     thumbnail_url, is_active, use_count)
                VALUES
                    (:id, :name, :type, CAST(:attributes AS json),
                     :injection_template, :thumbnail_url,
                     :is_active, :use_count)
                ON CONFLICT (id) DO NOTHING
            """),
            row,
        )
        inserted += result.rowcount
    return inserted


async def main() -> None:
    url = os.environ.get("DATABASE_URL", "")
    db_name = url.rsplit("/", 1)[-1].split("?")[0]
    if not db_name.endswith("_test"):
        raise SystemExit(
            f"REFUSING: database '{db_name}' does not end in '_test'.\n"
            "Set DATABASE_URL to the test database before running this script."
        )

    async with async_session() as session:
        async with session.begin():
            conn = await session.connection()
            n_models = await seed_ai_models(conn)
            n_templates = await seed_templates(conn)
            n_styles = await seed_style_profiles(conn)

    await engine.dispose()
    print(f"  ai_models:      {n_models} inserted")
    print(f"  templates:      {n_templates} inserted")
    print(f"  style_profiles: {n_styles} inserted")


if __name__ == "__main__":
    asyncio.run(main())

